#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* concat(const char *a, const char *b) {
    size_t len_a = strlen(a);
    size_t len = len_a + strlen(b) + 1;
    // 溢出回绕检查：和小于任一加数则溢出
    if (len < len_a) {
        return NULL;
    }
    char *buf = (char *)malloc(len);
    if (buf == NULL) return NULL;
    memcpy(buf, a, len_a);
    memcpy(buf + len_a, b, strlen(b));
    buf[len - 1] = '\0';
    return buf;
}

