#include <stdatomic.h>

typedef struct {
    void *data;
    atomic_int refcount;
} RefObject;

RefObject *ref_new(void *data) {
    RefObject *o = malloc(sizeof(RefObject));
    o->data = data;
    atomic_init(&o->refcount, 1);
    return o;
}

void ref_inc(RefObject *o) {
    if (o) atomic_fetch_add(&o->refcount, 1);
}

void ref_dec(RefObject *o) {
    if (!o) return;
    if (atomic_fetch_sub(&o->refcount, 1) == 1) {
        free(o->data);       /* 仅当引用计数归零时释放 */
        free(o);
    }
    /* 引用计数 > 0 时对象仍存活，安全访问 */
}

