int send_chunks(const char *data, size_t total_len) {
    if (data == NULL) return -1;
    size_t sent = 0;
    while (sent < total_len) {
        size_t remaining = total_len - sent;
        size_t this_chunk = remaining < CHUNK_SIZE ? remaining : CHUNK_SIZE;
