import java.io.*;

@RestController
public class FileViewerSafe {
    private static final Path BASE = Paths.get("/var/data/files").toAbsolutePath().normalize();

    @GetMapping("/view")
    public byte[] view(@RequestParam String file) throws IOException {
        if (file == null || file.isEmpty()) {
            throw new IllegalArgumentException("missing file");
        }
        Path target = BASE.resolve(file).normalize();
        if (!target.startsWith(BASE)) {
            throw new SecurityException("path traversal blocked");
        }
        return Files.readAllBytes(target);
    }
