            return True
    return False

@app.route('/api/admin/operation', methods=['POST'])
def admin_operation():
    # 获取客户端真实IP（考虑反向代理场景，使用X-Forwarded-For）
    forwarded_for = request.headers.get('X-Forwarded-For', '')
    if forwarded_for:
        # 取最左侧IP（客户端原始IP）
        client_ip = forwarded_for.split(',')[0].strip()
    else:
        client_ip = request.remote_addr or ''

    # 防御1：来源IP白名单校验
    if not is_trusted_source(client_ip):
        return jsonify({'error': 'Access denied'}), 403

    # 防御2：完整路径校验（必须精确匹配）
    # 防止路径遍历或子路径绕过
    allowed_path = '/api/admin/operation'
    if request.path != allowed_path:
        return jsonify({'error': 'Invalid path'}), 404

    # 防御3：请求方法白名单（仅允许POST）
    if request.method != 'POST':
