def validate_query(query):
    """白名单校验：只允许字母、数字、空格和常见查询符号"""
    if not query or len(query) > 200:
        return False
    # 严格白名单模式，拒绝任何不在允许列表中的字符
    return bool(re.fullmatch(r'[a-zA-Z0-9\s\-_*?=<>:]+', query))

