import java.io.*;
import java.util.*;

public class SafeDeserializer {
    private static final Set<String> ALLOWED_CLASSES = new HashSet<>(Arrays.asList(
        "com.example.model.User",
        "com.example.model.Order",
        "java.util.ArrayList",
        "java.util.HashMap"
    ));

    public static Object deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data)) {
            @Override
            protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
                String className = desc.getName();
                // 白名单校验：仅允许预定义的安全类
                if (!ALLOWED_CLASSES.contains(className)) {
                    throw new InvalidClassException("Forbidden class: " + className);
                }
                return super.resolveClass(desc);
            }
        }) {
            return ois.readObject();
        }
    }

    public static void main(String[] args) throws Exception {
        // 模拟序列化一个 User 对象
        byte[] userData = serializeUser();
        Object obj = deserialize(userData);
        System.out.println("Deserialized: " + obj.getClass().getName());
    }

    private static byte[] serializeUser() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(new com.example.model.User("alice", 25));
        }
        return baos.toByteArray();
    }
}

