import hashlib
import os
import json
from typing import Dict, Optional


class FileIntegrityVerifier:
    """文件完整性校验器 - 用于检测文件传输损坏，非密码学用途"""

    def __init__(self, manifest_path: str):
        self.manifest_path = manifest_path
        self._expected_hashes: Dict[str, str] = {}
        self._load_manifest()

    def _load_manifest(self) -> None:
        """加载校验清单（仅限内部可信来源生成）"""
        try:
            with open(self.manifest_path, 'r') as f:
                data = json.load(f)
                # 防御1: 白名单校验 - 仅接受预定义文件名的哈希
                allowed_files = {'config.ini', 'data.bin', 'assets.zip'}
                for filename, hash_val in data.items():
                    if filename in allowed_files and isinstance(hash_val, str) and len(hash_val) == 64:
                        self._expected_hashes[filename] = hash_val.lower()
        except (json.JSONDecodeError, IOError):
            # 防御2: 加载失败时置空，后续校验全部失败
            self._expected_hashes = {}

    def verify_file(self, filepath: str) -> bool:
        """验证文件完整性 - 使用SHA256仅用于错误检测"""
        # 防御3: 路径白名单 - 拒绝绝对路径和上级目录引用
        if os.path.isabs(filepath) or '..' in filepath:
            return False

        # 防御4: 文件名白名单 - 仅允许清单中已注册的文件
        if filepath not in self._expected_hashes:
            return False

        try:
            # 计算文件SHA256哈希（非密码学用途）
            sha256_hash = hashlib.sha256()
            with open(filepath, 'rb') as f:
                # 分块读取避免大文件内存问题
                for chunk in iter(lambda: f.read(8192), b''):
                    sha256_hash.update(chunk)

            actual_hash = sha256_hash.hexdigest().lower()
            # 防御5: 恒定时间比较（虽然非安全场景，但保持良好实践）
            expected = self._expected_hashes[filepath]
            return self._secure_compare(actual_hash, expected)

        except (IOError, PermissionError):
            return False

    @staticmethod
    def _secure_compare(a: str, b: str) -> bool:
        """恒定时间字符串比较"""
        if len(a) != len(b):
            return False
        result = 0
        for x, y in zip(a, b):
            result |= ord(x) ^ ord(y)
        return result == 0


def main():
    """演示入口 - 仅用于文件完整性校验"""
    verifier = FileIntegrityVerifier('manifest.json')

    test_files = ['config.ini', 'data.bin', 'assets.zip']
    for fname in test_files:
        # 校验结果仅用于提示文件是否损坏，不用于认证或授权
        if verifier.verify_file(fname):
            print(f"[OK] {fname} 完整性校验通过")
        else:
            print(f"[FAIL] {fname} 校验失败或文件不存在")


if __name__ == '__main__':
    main()

