def is_safe_redirect(target):
    """
    使用白名单校验重定向目标是否安全
    返回 True 表示安全，False 表示不安全
    """
    # 第10行：解析 URL，提取 host 和 path
    parsed = urllib.parse.urlparse(target)

    # 第12行：如果是相对路径（无 scheme 和 netloc），则校验 path 是否在白名单中
    if not parsed.scheme and not parsed.netloc:
        return parsed.path in ALLOWED_PATHS

    # 第15行：如果是绝对 URL，则校验 host 是否在白名单中
    if parsed.scheme in {"http", "https"}:
        return parsed.netloc in ALLOWED_HOSTS

    # 第18行：其他 scheme（如 javascript:）直接拒绝
    return False

@app.route("/redirect")
def safe_redirect():
    # 第22行：从请求参数获取目标 URL
    target = request.args.get("url", "")

    # 第24行：空值检查，防止无目标时重定向到根路径
    if not target:
        return abort(400)

    # 第27行：白名单校验，不通过则返回 400
    if not is_safe_redirect(target):
        return abort(400)

    # 第30行：通过校验后才执行重定向
    return redirect(target)

