import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.naming.InitialContext;
import javax.naming.NamingException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.sql.DataSource;

public class RedirectController {

    private static final String VALID_REDIRECT_PREFIX = "/internal/";

    public void handleRequest(HttpServletRequest request, HttpServletResponse response) 
            throws SQLException, NamingException {

        String token = request.getParameter("token");
        if (token == null || token.isEmpty()) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        String redirectUrl = getRedirectUrlFromDatabase(token);

        if (redirectUrl == null) {
            response.setStatus(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        // 防御：验证 URL 必须以内部路径前缀开头
        if (!redirectUrl.startsWith(VALID_REDIRECT_PREFIX)) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            return;
        }

        // 防御：确保不是绝对 URL（防止 //evil.com 绕过）
        if (redirectUrl.startsWith("//") || redirectUrl.contains("://")) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            return;
        }

        response.sendRedirect(redirectUrl);
    }

    private String getRedirectUrlFromDatabase(String token) throws SQLException, NamingException {
        InitialContext ctx = new InitialContext();
        DataSource ds = (DataSource) ctx.lookup("java:comp/env/jdbc/AppDB");

        String sql = "SELECT redirect_path FROM redirect_map WHERE token = ? AND active = 1";

        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, token);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return rs.getString("redirect_path");
                }
            }
        }
        return null;
    }
}

