const querySchema = new mongoose.Schema({
  username: { type: String, required: true, minlength: 3, maxlength: 20, match: /^[a-zA-Z0-9_]+$/ },
  role: { type: String, enum: ['user', 'admin', 'moderator'], default: 'user' },
  page: { type: Number, min: 1, max: 1000, default: 1 },
  limit: { type: Number, min: 1, max: 50, default: 10 }
});

const Query = mongoose.model('Query', querySchema);

// 查询用户列表 - 使用 schema 校验 + 白名单字段
exports.getUsers = async (req, res) => {
  try {
    // 从请求中提取参数，只允许白名单字段
    const { username, role, page, limit } = req.query;

    // 构建查询对象，只使用 schema 中定义的字段
    const queryParams = {};
    if (username) queryParams.username = username;
    if (role) queryParams.role = role;

    // 通过 schema 进行数据校验（参数化）
    const validated = new Query({
      username: queryParams.username || 'default_user',
      role: queryParams.role || 'user',
      page: parseInt(page) || 1,
      limit: parseInt(limit) || 10
    });

    // 校验失败会抛出 ValidationError
    await validated.validate();

    // 使用参数化查询（mongoose 自动处理类型转换）
    const filter = {};
    if (validated.username !== 'default_user') filter.username = validated.username;
    if (validated.role !== 'user') filter.role = validated.role;

    // 执行查询 - 只使用经过校验的值
    const users = await User.find(filter)
      .skip((validated.page - 1) * validated.limit)
      .limit(validated.limit)
      .select('-password -__v');

    res.json({
      success: true,
      data: users,
      pagination: {
        page: validated.page,
        limit: validated.limit
      }
    });
  } catch (error) {
    if (error.name === 'ValidationError') {
      return res.status(400).json({ success: false, message: 'Invalid query parameters' });
    }
    res.status(500).json({ success: false, message: 'Server error' });
  }
};

