const jwt = require('jsonwebtoken');
const crypto = require('crypto');

// 密钥管理：使用环境变量，避免硬编码
const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(64).toString('hex');
const JWT_ISSUER = 'auth-service';
const JWT_AUDIENCE = 'api-gateway';

/**
 * 生成访问令牌
 * @param {Object} payload - 用户信息
 * @param {string} userId - 用户ID
 * @returns {string} - JWT 字符串
 */
function generateToken(payload, userId) {
  // 限制 payload 中的敏感字段
  const safePayload = {
    sub: userId,
    role: payload.role || 'user',
    // 仅保留必要字段，避免注入额外数据
  };

  return jwt.sign(safePayload, JWT_SECRET, {
    algorithm: 'HS256',
    expiresIn: '15m',
    issuer: JWT_ISSUER,
    audience: JWT_AUDIENCE,
  });
}

/**
 * 验证并解析 JWT
 * @param {string} token - 待验证的 token
 * @returns {Object|null} - 解析后的 payload 或 null
 */
function verifyToken(token) {
  try {
    // 关键防御：显式指定算法白名单，防止算法混淆攻击
    const decoded = jwt.verify(token, JWT_SECRET, {
      algorithms: ['HS256'],  // 只允许 HS256
      issuer: JWT_ISSUER,
      audience: JWT_AUDIENCE,
    });
    return decoded;
  } catch (error) {
    // 所有验证失败均返回 null，不泄露具体错误信息
    console.error('Token verification failed:', error.message);
    return null;
  }
}

/**
 * 中间件：验证请求头中的 Bearer Token
 * @param {Object} req - 请求对象
 * @param {Object} res - 响应对象
 * @param {Function} next - 下一个中间件
 */
function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid authorization header' });
  }

  const token = authHeader.slice(7);
  const decoded = verifyToken(token);

  if (!decoded) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }

  // 将已验证的用户信息挂载到请求对象
  req.user = {
    id: decoded.sub,
    role: decoded.role,
  };
  next();
}

module.exports = { generateToken, verifyToken, authMiddleware };

