    'alice': {'password': 'hashed_password_1', 'role': 'admin'},
    'bob': {'password': 'hashed_password_2', 'role': 'user'}
}

def login_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # 检查 session 中是否存在用户标识
        if 'user_id' not in session:
            # 未登录，重定向到登录页
            return redirect(url_for('login'))

        # 检查用户是否仍然存在于系统中（防止已删除用户的 session 继续有效）
        user_id = session['user_id']
        if user_id not in USERS:
            # 用户已不存在，清除 session 并重定向
            session.clear()
            return redirect(url_for('login'))

        # 检查用户角色（非必需，但增加一层防御）
        if session.get('role') != USERS[user_id]['role']:
            # 角色不匹配，可能存在 session 篡改，强制重新登录
            session.clear()
            return redirect(url_for('login'))

        return f(*args, **kwargs)
    return decorated_function

