    # 仅管理员可访问的管理面板
    if session.get('role') != 'admin':
        abort(403)  # 禁止访问
    return 'Welcome to the admin dashboard, {}!'.format(session['user_id'])

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=False)

