```java
import org.springframework.expression.Expression;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.SimpleEvaluationContext;
import org.springframework.stereotype.Service;

import java.util.HashMap;
import java.util.Map;

@Service
public class ExpressionService {

    private final SpelExpressionParser parser = new SpelExpressionParser();

    /**
     * 安全评估用户提供的SpEL表达式，仅允许属性访问和数学运算。
     * 禁止方法调用、类型引用、构造器调用等危险操作。
     */
    public Object evaluateUserExpression(String userExpression, Map<String, Object> contextData) {
        // 1. 建立受限的评估上下文 - 只允许属性访问、数学运算、比较等安全操作
        SimpleEvaluationContext context = SimpleEvaluationContext
                .forReadOnlyDataBinding()
                .withInstanceMethods()  // 注意：这里允许实例方法，但后续有额外校验
                .build();

        // 2. 对输入进行基础校验 - 拒绝包含危险关键字的表达式
        if (containsForbiddenKeyword(userExpression)) {
            throw new IllegalArgumentException("表达式包含不允许的操作");
        }

        // 3. 将业务数据绑定到上下文中（仅暴露安全属性）
        context.setVariable("data", contextData);

        // 4. 解析并执行表达式 - 在受限上下文中运行
        Expression expression = parser.parseExpression(userExpression);
        return expression.getValue(context);  // 第25行 - 关键执行点
    }

    /**
     * 检查表达式是否包含危险关键字（黑名单+白名单双重防御）
     */
    private boolean containsForbiddenKeyword(String expression) {
        // 黑名单：明确禁止的危险操作符
        String[] forbidden = {
            "T(",          // 类型引用
            "new ",        // 构造器
            ".getClass",   // 反射
            "exec",        // 命令执行
            "Runtime",     // 运行时
            "ProcessBuilder"
        };
        for (String keyword : forbidden) {
            if (expression.contains(keyword)) {
                return true;
            }
        }

        // 白名单增强：仅允许属性路径（字母数字、点、下划线、方括号）
        // 拒绝任何包含括号（方法调用特征）的表达式
        if (expression.contains("(")) {
            // 第40行 - 但允许简单的数学运算如 (a + b)
            if (!expression.matches("^[\\w\\s.\\[\\]()+\\-*/%<>=!&|]+$")) {
                return true;
            }
            // 进一步限制：括号内不能包含字母（排除方法调用如 foo()）
            if (expression.matches(".*\\([a-zA-Z].*\\).*")) {
                return true;
            }
        }
        return false;
    }

    /**
     * 测试入口 - 演示安全行为
     */
    public static void main(String[] args) {
        ExpressionService service = new ExpressionService();
        Map<String, Object> data = new HashMap<>();
        data.put("price", 100);
        data.put("quantity", 3);

        // 安全表达式：数学运算
        Object result = service.evaluateUserExpression("#data['price'] * #data['quantity']", data);
        System.out.println("结果: " + result); // 输出 300

        // 恶意表达式尝试：将被拒绝
        try {
            service.evaluateUserExpression("T(java.lang.Runtime).getRuntime().exec('ls')", data);
        } catch (IllegalArgumentException e) {
            System.out.println("已拦截: " + e.getMessage());
        }
    }
}

